model:
class Animal {
  age:Int = 0
  name:String = "unknown"
}

class Dog extending Animal {
  breed:String = "mixed"
  dogBreed:String = breed
}

class Cat extending Animal {
  indoor:Bool = true
  isIndoor:Bool = indoor
}

dog:Dog

cat:Cat

inferredBreed:String = dog.breed

inferredIndoor:Bool = cat.indoor

req dog.breed = "mixed"

req cat.indoor = true
